steps.script:
var w = ctx.win;
var card = w.webCpu && w.webCpu.cards && w.webCpu.cards.loginRegCard;
if (!card || !card.task || typeof card.task.confirmCallback !== 'function') return 'already';
card.task.confirmCallback({ account: ctx.vars.email, checkNumber: ctx.secrets.ADMIN_PASSWORD });
for (var i = 0; i < 40; i++) {
  if (w.localStorage.logined === 'true') return 'ok';
  await new Promise(function (r) { w.setTimeout(r, 500); });
}
throw new Error('登录超时');

var w = ctx.win;
for (var i = 0; i < 40; i++) {
  var c = w.webCpu.cards.loadScriptCard;
  if (c && c.task && c.task.vueItem) {
    c.task.vueItem.type = 'webScript';
    c.task.vueItem.valueMap['webScript'] = ctx.vars.agentScript;
    return true;
  }
  await new Promise(function (r) { w.setTimeout(r, 500); });
}
throw new Error('弹窗未出现');

var w = ctx.win;
for (var i = 0; i < 60; i++) {
  var c = w.webCpu.cards.loadScriptCard;
  var vm = c && c.task && c.task.vueItem;
  if (vm && vm.currentList && vm.currentList.length) {
    await new Promise(function (resolve) {
      vm._confirmLoadScript(function () { resolve(); });
    });
    w.location.href = '/clone.html?aScript=assets/animationScripts/initTools.js';
    return true;
  }
  await new Promise(function (r) { w.setTimeout(r, 500); });
}
throw new Error('脚本列表为空');
